CREATE TABLE public.employees(id bigint primary key,deleted_at timestamptz,owner_company_id bigint,branch_id bigint,designation_id bigint,photo_dms_document_id bigint,full_name_en text);
CREATE TABLE public.erp_user_employee_links(user_profile_id bigint,employee_id bigint);
CREATE TABLE public.designations(id bigint,owner_company_id bigint,designation_name_en text);
CREATE FUNCTION erp_private.employee_permission(bigint,text) RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
CREATE FUNCTION public.current_user_can_view_dms_document(bigint) RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
CREATE FUNCTION erp_private.document_permission(bigint,text) RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
CREATE TABLE erp_private.mobile_dms_shares(id bigint,token_hash text,recipient bigint,issuer bigint,revoked_at timestamptz,expires_at timestamptz);
CREATE FUNCTION erp_private.mobile_dms_share_source(erp_private.mobile_dms_shares,text[]) RETURNS jsonb LANGUAGE sql AS $$SELECT NULL::jsonb$$;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
INSERT INTO auth.users SELECT auth_user_id FROM public.user_profiles;
CREATE FUNCTION public.fixture_chat_permit(p bigint,f text,cmd jsonb) RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE ticket uuid:=gen_random_uuid(); session_id uuid:=lpad(p::text,32,'0')::uuid;
BEGIN
 INSERT INTO erp_comm_cost.proof(operation_id,scope,actor_id,feature,operational_stop_by,valid_until,max_meter_age,shutdown_evidence,headroom_micros)
 VALUES(ticket::text,'communications',p::text,f::erp_comm_cost.feature,now()+interval '1 minute',now()+interval '1 minute',interval '1 minute','synthetic test fixture',0);
 INSERT INTO erp_comm_cost.reservation(operation_id,permit_id,scope,actor_id,feature,floor_micros,reserved_micros,issued_at,expires_at,actor_session,command_hash)
 VALUES(ticket::text,ticket,'communications',p::text,f::erp_comm_cost.feature,0,0,now(),now()+interval '1 minute',session_id,sha256(convert_to(cmd::text,'UTF8')));
 RETURN ticket;
END $$;
REVOKE ALL ON FUNCTION public.fixture_chat_permit(bigint,text,jsonb) FROM PUBLIC;
